/**
 * Deploy command handler
 */
import { deployCommand, parseDeployArgs } from "./command.js";
import { showHeader } from "../../utils/index.js";
import { parseArgsOrThrow } from "../../shared/args.js";
import { ensureCliBundlerContracts } from "../../shared/default-contracts.js";
const defaultDependencies = {
    ensureBundlerContracts: ensureCliBundlerContracts,
    deploy: deployCommand,
};
export async function handleDeployCommand(args, dependencies = defaultDependencies) {
    showHeader();
    const options = parseArgsOrThrow(parseDeployArgs, "deploy", args);
    await dependencies.ensureBundlerContracts();
    await dependencies.deploy(options);
}
